    }
}

public sealed class LocalFunctionStatement : IStatement
{
    public List<ISyntax> AttributeLists { get; } = new();
    public List<ISyntax> Modifiers { get; } = new();
    public ITypeDefinition? ReturnType { get; set; }
    public string Identifier { get; set; }
    public ISyntax? TypeParameterList { get; set; }
    public ISyntax? ParameterList { get; set; }
    public List<ISyntax> ConstraintClauses { get; } = new();
    public IStatement? Body { get; set; }
    public ISyntax? ExpressionBody { get; set; }

    public LocalFunctionStatement(ITypeDefinition returnType, string identifier, ISyntax parameterList, IStatement body, ISyntax expressionBody)
    {
        ReturnType = returnType;
        Identifier = identifier;
        ParameterList = parameterList;
        Body = body;
        ExpressionBody = expressionBody;
    }

    public void AddUsingNamespace(string ns) { }

    public void WriteOutput(IOutputContext outputContext)
    {
        for (var i = 0; i < AttributeLists.Count; i++)
        {
            AttributeLists[i].WriteOutput(outputContext);
        }
        for (var i = 0; i < Modifiers.Count; i++)
        {
            Modifiers[i].WriteOutput(outputContext);
        }
        if (ReturnType != null) outputContext.Write(ReturnType);
        Tk.W(outputContext, Identifier);
        TypeParameterList?.WriteOutput(outputContext);
        ParameterList?.WriteOutput(outputContext);
        for (var i = 0; i < ConstraintClauses.Count; i++)
        {
            ConstraintClauses[i].WriteOutput(outputContext);
        }
        Body?.WriteOutput(outputContext);
        ExpressionBody?.WriteOutput(outputContext);
        Tk.W(outputContext, ";");
    }
}

