    public List<ISyntax> TextTokens { get; } = new();

    public XmlCDataSection() { }

    public void AddUsingNamespace(string ns) { }

    public void WriteOutput(IOutputContext outputContext)
    {
        Tk.W(outputContext, "<![CDATA[");
        for (var i = 0; i < TextTokens.Count; i++)
        {
            TextTokens[i].WriteOutput(outputContext);
        }
        Tk.W(outputContext, "]]>");
    }
}

public sealed class XmlComment : IXmlNode
{
    public List<ISyntax> TextTokens { get; } = new();

    public XmlComment() { }

    public void AddUsingNamespace(string ns) { }

    public void WriteOutput(IOutputContext outputContext)
    {
        Tk.W(outputContext, "<!--");
        for (var i = 0; i < TextTokens.Count; i++)
        {
            TextTokens[i].WriteOutput(outputContext);
        }
        Tk.W(outputContext, "-->");
    }
}

public sealed class IfDirectiveTrivia : IDirectiveTrivia
{
    public IExpression? Condition { get; set; }
    public string EndOfDirectiveToken { get; set; }
    public ISyntax? IsActive { get; set; }
    public ISyntax? BranchTaken { get; set; }
    public ISyntax? ConditionValue { get; set; }

    public IfDirectiveTrivia(IExpression condition, string endOfDirectiveToken, ISyntax isActive, ISyntax branchTaken, ISyntax conditionValue)
    {
        Condition = condition;
        EndOfDirectiveToken = endOfDirectiveToken;
        IsActive = isActive;
        BranchTaken = branchTaken;
        ConditionValue = conditionValue;
    }

    public void AddUsingNamespace(string ns) { }

    public void WriteOutput(IOutputContext outputContext)
    {
        Tk.W(outputContext, "#");
        Tk.W(outputContext, "if");
        Condition?.WriteOutput(outputContext);
        Tk.W(outputContext, EndOfDirectiveToken);
        IsActive?.WriteOutput(outputContext);
        BranchTaken?.WriteOutput(outputContext);
        ConditionValue?.WriteOutput(outputContext);
    }
}

