    public ISyntax? Start { get; set; }
    public ISyntax? End { get; set; }
    public string CharacterOffset { get; set; }
    public string File { get; set; }
    public string EndOfDirectiveToken { get; set; }
    public ISyntax? IsActive { get; set; }

    public LineSpanDirectiveTrivia(ISyntax start, ISyntax end, string characterOffset, string file, string endOfDirectiveToken, ISyntax isActive)
    {
        Start = start;
        End = end;
        CharacterOffset = characterOffset;
        File = file;
        EndOfDirectiveToken = endOfDirectiveToken;
        IsActive = isActive;
    }

    public void AddUsingNamespace(string ns) { }

    public void WriteOutput(IOutputContext outputContext)
    {
        Tk.W(outputContext, "#");
        Tk.W(outputContext, "line");
        Start?.WriteOutput(outputContext);
        Tk.W(outputContext, "-");
        End?.WriteOutput(outputContext);
        Tk.W(outputContext, CharacterOffset);
        Tk.W(outputContext, File);
        Tk.W(outputContext, EndOfDirectiveToken);
        IsActive?.WriteOutput(outputContext);
    }
}

public sealed class PragmaWarningDirectiveTrivia : IDirectiveTrivia
{
    public string DisableOrRestoreKeyword { get; set; }
    public List<IExpression> ErrorCodes { get; } = new();
    public string EndOfDirectiveToken { get; set; }
    public ISyntax? IsActive { get; set; }

    public PragmaWarningDirectiveTrivia(string disableOrRestoreKeyword, string endOfDirectiveToken, ISyntax isActive)
    {
        DisableOrRestoreKeyword = disableOrRestoreKeyword;
        EndOfDirectiveToken = endOfDirectiveToken;
        IsActive = isActive;
    }

    public void AddUsingNamespace(string ns) { }

    public void WriteOutput(IOutputContext outputContext)
    {
        Tk.W(outputContext, "#");
        Tk.W(outputContext, "pragma");
        Tk.W(outputContext, "warning");
        Tk.W(outputContext, DisableOrRestoreKeyword);
        for (var i = 0; i < ErrorCodes.Count; i++)
        {
            if (i > 0) outputContext.Write(", ");
            ErrorCodes[i].WriteOutput(outputContext);
        }
        Tk.W(outputContext, EndOfDirectiveToken);
        IsActive?.WriteOutput(outputContext);
    }
}

